package com.forgeflow.workerservice.service;
import com.fasterxml.jackson.databind.ObjectMapper; import com.forgeflow.workerservice.api.JobApiClient; import org.slf4j.*; import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.stereotype.Component; import java.util.concurrent.atomic.AtomicInteger;
@Component public class JobConsumer {
 private static final Logger log=LoggerFactory.getLogger(JobConsumer.class); private final JobApiClient api; private final TaskExecutor executor; private final ObjectMapper mapper; private final String workerId=System.getenv().getOrDefault("WORKER_ID","worker-"+java.util.UUID.randomUUID().toString().substring(0,8)); private final AtomicInteger active=new AtomicInteger();
 public JobConsumer(JobApiClient api,TaskExecutor executor,ObjectMapper mapper){this.api=api;this.executor=executor;this.mapper=mapper;}
 @RabbitListener(queues="forgeflow.jobs") public void consume(String jobId){var claim=api.claim(jobId,workerId);if(claim==null||!claim.claimed()||claim.job()==null){log.debug("Job {} was already claimed or is no longer eligible",jobId);return;}active.incrementAndGet();try{var result=executor.execute(claim.job());api.complete(jobId,workerId,result);log.info("Job {} completed in attempt {}",jobId,claim.job().attempts());}catch(Exception ex){String error=ex.getMessage()==null?ex.getClass().getSimpleName():ex.getMessage();log.warn("Job {} failed on attempt {}: {}",jobId,claim.job().attempts(),error);try{api.fail(jobId,workerId,error);}catch(Exception reportFailure){log.error("Could not report failure for job {}. Job lease recovery will handle it: {}",jobId,reportFailure.getMessage());}}finally{active.decrementAndGet();}}
 public int activeJobs(){return active.get();} public String workerId(){return workerId;}
}
